package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.context.JXPathContextFactory;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.PropertyOwnerPointer;
import org.apache.commons.jxpath.ri.model.QName;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class NullPropertyPointer_createPath_TriageGen0Test {

    private JXPathContext mockContext;
    private JXPathContextFactory mockFactory;
    private QName mockQName;

    @Before
    public void setUp() {
        mockContext = mock(JXPathContext.class);
        mockFactory = mock(JXPathContextFactory.class);
        mockQName = mock(QName.class);
        when(mockContext.getFactory()).thenReturn(mockFactory);
    }

    /**
     * Test Case: isAttribute() is true.
     * Coverage: Branch 'if (isAttribute())'
     */
    @Test
    public void testCreatePath_IsAttribute() {
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttributePointer = mock(NodePointer.class);

        // We need to spy or subclass because isAttribute() is likely protected/internal
        // Since we can't modify the source, we assume the behavior is driven by internal state
        // For this test, we assume a way to trigger isAttribute() or we mock the behavior if possible.
        // However, since we are testing the class itself, we use a subclass to control isAttribute.

        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent) {
            @Override
            public QName getName() { return mockQName; }
            @Override
            protected boolean isAttribute() { return true; } // Force branch
        };

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(mockContext, mockQName)).thenReturn(mockAttributePointer);

        NodePointer result = nullPropertyPointer.createPath(mockContext);

        assertNotNull(result);
        assertEquals(mockAttributePointer, result);
        verify(mockNewParent).createAttribute(mockContext, mockQName);
    }

    /**
     * Test Case: isAttribute() is false AND parent is NullPointer.
     * Coverage: Branch 'if (parent instanceof NullPointer)' -> throws exception.
     */
    @Test(expected = RuntimeException.class) // Exception type depends on createBadFactoryException implementation
    public void testCreatePath_IsAttributeFalse_ParentIsNullPointer() {
        NodePointer nullPointer = mock(NullPointer.class);
        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(nullPointer) {
            @Override
            protected boolean isAttribute() { return false; }
        };

        // The method calls parent.createPath(context) first. 
        // If parent is NullPointer, it might throw or return something.
        // The logic says: if (parent instanceof NullPointer) throw ...
        // This implies we must ensure parent.createPath does not throw before the check.
        when(nullPointer.createPath(mockContext)).thenReturn(mock(NodePointer.class));

        nullPropertyPointer.createPath(mockContext);
    }

    /**
     * Test Case: isAttribute() is false, parent is NOT NullPointer, 
     * and newParent IS PropertyOwnerPointer.
     * Coverage: Branch 'if (newParent instanceof PropertyOwnerPointer)'
     */
    @Test
    public void testCreatePath_IsAttributeFalse_NewParentIsPropertyOwnerPointer() {
        NodePointer mockParent = mock(NodePointer.class);
        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropPointer = mock(NodePointer.class);
        NodePointer mockFinalChild = mock(NodePointer.class);
        QName name = mock(QName.class);

        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent) {
            @Override
            public QName getName() { return name; }
            @Override
            public int getIndex() { return 0; }
            @Override
            protected boolean isAttribute() { return false; }
        };

        when(mockParent.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropPointer);
        when(mockPropPointer.createChild(mockContext, name, 0)).thenReturn(mockFinalChild);

        NodePointer result = nullPropertyPointer.createPath(mockContext);

        assertNotNull(result);
        assertEquals(mockFinalChild, result);
        verify(mockPop).getPropertyPointer();
        verify(mockPropPointer).createChild(mockContext, name, 0);
    }

    /**
     * Test Case: isAttribute() is false, parent is NOT NullPointer, 
     * and newParent is NOT PropertyOwnerPointer.
     * Coverage: Default else branch.
     */
    @Test
    public void testCreatePath_IsAttributeFalse_NewParentIsNotPropertyOwnerPointer() {
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockFinalChild = mock(NodePointer.class);
        QName name = mock(QName.class);

        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent) {
            @Override
            public QName getName() { return name; }
            @Override
            public int getIndex() { return 5; }
            @Override
            protected boolean isAttribute() { return false; }
        };

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createChild(mockContext, name, 5)).thenReturn(mockFinalChild);

        NodePointer result = nullPropertyPointer.createPath(mockContext);

        assertNotNull(result);
        assertEquals(mockFinalChild, result);
        verify(mockNewParent).createChild(mockContext, name, 5);
    }
}

/**
 * Mocking NullPointer for the purpose of the test class 
 * since it's a specific type within the package.
 */
class NullPointer extends NodePointer {
    public NullPointer() { super(null); }
    @Override
    public NodePointer createPath(JXPathContext context) { return this; }
}
